"use client";

import * as React from "react";
import * as ReactDOM from "react-dom";
import { useEditor, EditorContent } from "@tiptap/react";
import StarterKit from "@tiptap/starter-kit";
import Underline from "@tiptap/extension-underline";
import { Color } from "@tiptap/extension-color";
import { TextStyle } from "@tiptap/extension-text-style";
import Highlight from "@tiptap/extension-highlight";
import TextAlign from "@tiptap/extension-text-align";
import Link from "@tiptap/extension-link";
import { cn } from "@/lib/utils";
import {
  type FormattingTextType,
  toFontSizeValue,
} from "./formatting-options";
import { useEditorToolbar } from "./editor-toolbar-context";
import {
  createSlashExtension,
  type SlashCallbacks,
  type SlashItem,
} from "./slash-command-extension";

// ─── Extend TextStyle with fontSize ──────────────────────────────────────────

const TextStyleExtended = TextStyle.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      fontSize: {
        default: null,
        parseHTML: (el: HTMLElement) => el.style.fontSize || null,
        renderHTML: (attrs: Record<string, unknown>) =>
          attrs.fontSize ? { style: `font-size: ${attrs.fontSize}` } : {},
      },
    };
  },
});

// ─── Slash menu state ─────────────────────────────────────────────────────────

type SlashMenuState = {
  items: SlashItem[];
  rect: DOMRect | null;
  selectedIndex: number;
  execCommand: (i: number) => void;
};

// ─── RichTextEditor ───────────────────────────────────────────────────────────

export function RichTextEditor({
  value,
  onChange,
  editable = false,
  className,
  style,
  defaultTextType = "p",
  defaultFontSize,
}: {
  value: string;
  onChange?: (html: string) => void;
  editable?: boolean;
  className?: string;
  style?: React.CSSProperties;
  defaultTextType?: FormattingTextType;
  defaultFontSize?: string;
}) {
  // Slash menu state
  const [slashMenu, setSlashMenu] = React.useState<SlashMenuState | null>(null);
  const slashMenuRef = React.useRef<SlashMenuState | null>(null);
  slashMenuRef.current = slashMenu;

  // Stable callbacks ref updated each render so TipTap always gets fresh closures
  const callbacksRef = React.useRef<SlashCallbacks>({
    onStart:  () => {},
    onUpdate: () => {},
    onClose:  () => {},
    onKeyDown: () => false,
  });
  callbacksRef.current = {
    onStart: (items, getRect, execCommand) => {
      setSlashMenu({ items, rect: getRect(), selectedIndex: 0, execCommand });
    },
    onUpdate: (items, getRect, execCommand) => {
      setSlashMenu((prev) =>
        prev ? { ...prev, items, rect: getRect(), selectedIndex: 0, execCommand } : null,
      );
    },
    onClose: () => setSlashMenu(null),
    onKeyDown: (event) => {
      const cur = slashMenuRef.current;
      if (!cur) return false;
      if (event.key === "ArrowDown") {
        setSlashMenu((m) =>
          m ? { ...m, selectedIndex: (m.selectedIndex + 1) % m.items.length } : null,
        );
        return true;
      }
      if (event.key === "ArrowUp") {
        setSlashMenu((m) =>
          m ? { ...m, selectedIndex: (m.selectedIndex - 1 + m.items.length) % m.items.length } : null,
        );
        return true;
      }
      if (event.key === "Enter") {
        cur.execCommand(cur.selectedIndex);
        return true;
      }
      if (event.key === "Escape") {
        setSlashMenu(null);
        return true;
      }
      return false;
    },
  };

  // Slash extension created once per editor instance
  const [slashExt] = React.useState(() => createSlashExtension(callbacksRef));

  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading:         { levels: [1, 2, 3] },
        codeBlock:       false,
        horizontalRule:  false,
        // starter-kit v3 ships these too; we add our own configured ones below
        link:            false,
        underline:       false,
      }),
      Underline,
      TextStyleExtended,
      Color,
      Highlight.configure({ multicolor: true }),
      TextAlign.configure({ types: ["paragraph", "heading"] }),
      Link.configure({ openOnClick: false, defaultProtocol: "https" }),
      slashExt,
    ],
    content: value || "<p></p>",
    editable,
    onUpdate: ({ editor }) => {
      onChange?.(editor.getHTML());
    },
    editorProps: {
      attributes: { class: "focus:outline-none" },
    },
    immediatelyRender: false,
  });

  // Sync editable prop
  React.useEffect(() => {
    if (!editor) return;
    editor.setEditable(editable);
  }, [editor, editable]);

  // Sync external value without clobbering an active cursor
  React.useEffect(() => {
    if (!editor || editor.view.hasFocus()) return;
    if (value !== editor.getHTML()) {
      editor.commands.setContent(value || "", { emitUpdate: false });
    }
  }, [editor, value]);

  // Register as the active editor for the pinned formatting toolbar. A single
  // block can mount several editable editors at once (a Text block has a
  // heading + body; an Article Card has a headline + body). Registering on
  // mount would let whichever mounts last hijack the toolbar, so formatting
  // always hit the wrong field. Instead the first editor claims the toolbar so
  // it appears immediately, and *focus* re-targets it to whichever field the
  // cursor is actually in. Cleanup only clears if we're still the active one.
  const { setActiveEditor } = useEditorToolbar();
  React.useEffect(() => {
    if (!editable || !editor) return;
    setActiveEditor((cur) => cur ?? editor);
    const claim = () => setActiveEditor(editor);
    editor.on("focus", claim);
    return () => {
      editor.off("focus", claim);
      setActiveEditor((cur) => (cur === editor ? null : cur));
    };
  }, [editable, editor, setActiveEditor]);

  const resolvedDefaultFontSize =
    defaultFontSize ?? toFontSizeValue(style?.fontSize);

  return (
    <div
      data-letterstack-rich-text
      data-default-text-type={defaultTextType}
      data-default-font-size={resolvedDefaultFontSize}
      className={cn("relative", className)}
      style={style}
    >
      <EditorContent
        editor={editor}
        className={cn(
          "[&_.ProseMirror]:outline-none",
          "[&_.ProseMirror_p]:m-0",
          "[&_.ProseMirror_p+p]:mt-1",
          "[&_.ProseMirror_h2]:m-0 [&_.ProseMirror_h2]:font-extrabold",
          "[&_.ProseMirror_h3]:m-0 [&_.ProseMirror_h3]:font-bold",
          "[&_.ProseMirror_blockquote]:border-l-2 [&_.ProseMirror_blockquote]:border-current/30 [&_.ProseMirror_blockquote]:pl-3 [&_.ProseMirror_blockquote]:opacity-75",
          "[&_.ProseMirror_ul]:pl-4 [&_.ProseMirror_ul]:list-disc",
          "[&_.ProseMirror_ol]:pl-4 [&_.ProseMirror_ol]:list-decimal",
          editable && [
            "[&_.ProseMirror]:border-b [&_.ProseMirror]:border-dashed [&_.ProseMirror]:border-current/20",
            "[&_.ProseMirror:focus-within]:border-current/40",
          ],
        )}
      />

      {/* ── Slash command menu ──────────────────────────────────────────── */}
      {editable && slashMenu && slashMenu.rect && typeof document !== "undefined" &&
        ReactDOM.createPortal(
          <SlashCommandMenu
            items={slashMenu.items}
            selectedIndex={slashMenu.selectedIndex}
            rect={slashMenu.rect}
            onSelect={(i) => slashMenu.execCommand(i)}
          />,
          document.body,
        )}
    </div>
  );
}

// ─── Slash command popup ──────────────────────────────────────────────────────

function SlashCommandMenu({
  items,
  selectedIndex,
  rect,
  onSelect,
}: {
  items: SlashItem[];
  selectedIndex: number;
  rect: DOMRect;
  onSelect: (i: number) => void;
}) {
  if (items.length === 0) return null;

  return (
    <div
      style={{
        position: "fixed",
        top: rect.bottom + 6,
        left: rect.left,
        zIndex: 9999,
      }}
      className="min-w-[180px] overflow-hidden rounded-lg border bg-card shadow-xl"
    >
      {items.map((item, i) => (
        <button
          key={item.title}
          type="button"
          className={cn(
            "flex w-full flex-col px-3 py-2 text-left transition-colors",
            i === selectedIndex ? "bg-accent text-accent-foreground" : "hover:bg-muted",
          )}
          onMouseDown={(e) => {
            e.preventDefault();
            onSelect(i);
          }}
        >
          <span className="text-[13px] font-medium">{item.title}</span>
          <span className="text-[11px] text-muted-foreground">{item.subtitle}</span>
        </button>
      ))}
    </div>
  );
}

import { Extension } from "@tiptap/core";
import Suggestion from "@tiptap/suggestion";
import type { Editor } from "@tiptap/core";

export type SlashItem = {
  title: string;
  subtitle: string;
  run: (editor: Editor) => void;
};

export const SLASH_ITEMS: SlashItem[] = [
  { title: "Paragraph",     subtitle: "Default text block",    run: (e) => e.chain().focus().setParagraph().run() },
  { title: "Heading 2",     subtitle: "Large section heading", run: (e) => e.chain().focus().setHeading({ level: 2 }).run() },
  { title: "Heading 3",     subtitle: "Medium heading",        run: (e) => e.chain().focus().setHeading({ level: 3 }).run() },
  { title: "Bullet list",   subtitle: "Unordered list",        run: (e) => e.chain().focus().toggleBulletList().run() },
  { title: "Numbered list", subtitle: "Ordered list",          run: (e) => e.chain().focus().toggleOrderedList().run() },
  { title: "Quote",         subtitle: "Block quotation",       run: (e) => e.chain().focus().toggleBlockquote().run() },
];

export type SlashCallbacks = {
  onStart:  (items: SlashItem[], getRect: () => DOMRect | null, exec: (i: number) => void) => void;
  onUpdate: (items: SlashItem[], getRect: () => DOMRect | null, exec: (i: number) => void) => void;
  onClose:  () => void;
  onKeyDown:(event: KeyboardEvent) => boolean;
};

export function createSlashExtension(callbacksRef: { current: SlashCallbacks }) {
  return Extension.create({
    name: "slashCommand",
    addProseMirrorPlugins() {
      return [
        Suggestion({
          editor: this.editor,
          char: "/",
          allowSpaces: false,
          startOfLine: false,
          items: ({ query }: { query: string }) =>
            SLASH_ITEMS.filter((item) =>
              item.title.toLowerCase().includes(query.toLowerCase()),
            ).slice(0, 8),
          render: () => ({
            onStart: (props) => {
              const items = props.items as SlashItem[];
              const getRect = (props.clientRect ?? (() => null)) as () => DOMRect | null;
              callbacksRef.current.onStart(items, getRect, (i) => props.command(items[i]));
            },
            onUpdate: (props) => {
              const items = props.items as SlashItem[];
              const getRect = (props.clientRect ?? (() => null)) as () => DOMRect | null;
              callbacksRef.current.onUpdate(items, getRect, (i) => props.command(items[i]));
            },
            onExit:   () => callbacksRef.current.onClose(),
            onKeyDown: ({ event }) => callbacksRef.current.onKeyDown(event),
          }),
          command: ({ editor, range, props }) => {
            editor.commands.deleteRange(range);
            (props as SlashItem).run(editor);
          },
        }),
      ];
    },
  });
}

"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import {
  Copy01Icon,
  Delete02Icon,
  DragDropVerticalIcon,
} from "@hugeicons/core-free-icons";
import { cn } from "@/lib/utils";
import { type EmailBlock, type TextAlign } from "@/lib/email/document";
import { BLOCK_LABELS } from "./editor-types";

/**
 * Canva-style floating action bar that hovers above the selected block.
 * Block-level operations only (reorder / align / duplicate / delete) — inline
 * text formatting lives in the TipTap BubbleMenu inside RichTextEditor.
 */
export function BlockBubbleMenu({
  block,
  canRemove,
  isDragging,
  dragHandleProps,
  onDuplicate,
  onRemove,
  onAlign,
}: {
  block: EmailBlock;
  canRemove: boolean;
  isDragging: boolean;
  /** Spread of dnd-kit `useSortable` attributes + listeners for the drag handle. */
  dragHandleProps: React.HTMLAttributes<HTMLButtonElement>;
  onDuplicate: () => void;
  onRemove: () => void;
  onAlign: (align: TextAlign) => void;
}) {
  const align = "align" in block ? block.align : undefined;

  return (
    <div
      className={cn(
        // Vertical strip pinned just outside the block's right edge, so it no
        // longer collides with the pinned text formatting toolbar up top.
        "absolute right-0 top-1 z-30 translate-x-[calc(100%+10px)]",
        "flex flex-col items-center gap-0.5 rounded-lg border bg-card p-1 shadow-lg",
        // Don't let the floating bar trigger the block's own click handlers
        "pointer-events-auto",
      )}
      onClick={(e) => e.stopPropagation()}
      onMouseDown={(e) => e.stopPropagation()}
    >
      {/* Drag handle — the primary dnd affordance */}
      <button
        {...dragHandleProps}
        type="button"
        title={`Drag to reorder ${BLOCK_LABELS[block.type]}`}
        aria-label="Drag to reorder block"
        className={cn(
          "flex h-7 w-7 items-center justify-center rounded touch-none select-none",
          "text-muted-foreground transition-colors",
          "hover:bg-muted hover:text-foreground",
          isDragging ? "cursor-grabbing bg-primary/10 text-primary" : "cursor-grab",
        )}
      >
        <HugeiconsIcon icon={DragDropVerticalIcon} strokeWidth={2.5} className="size-4 opacity-70" />
      </button>

      {align !== undefined && (
        <>
          <Divider />
          <BubbleButton active={align === "left"} onClick={() => onAlign("left")} title="Align left">
            <AlignLeftIcon />
          </BubbleButton>
          <BubbleButton active={align === "center"} onClick={() => onAlign("center")} title="Align center">
            <AlignCenterIcon />
          </BubbleButton>
          <BubbleButton active={align === "right"} onClick={() => onAlign("right")} title="Align right">
            <AlignRightIcon />
          </BubbleButton>
        </>
      )}

      <Divider />

      <BubbleButton onClick={onDuplicate} title="Duplicate">
        <HugeiconsIcon icon={Copy01Icon} strokeWidth={2} className="size-3.5" />
      </BubbleButton>

      <Divider />

      <BubbleButton
        onClick={onRemove}
        disabled={!canRemove}
        title="Delete"
        className="text-destructive/70 hover:bg-destructive/10 hover:text-destructive"
      >
        <HugeiconsIcon icon={Delete02Icon} strokeWidth={2} className="size-3.5" />
      </BubbleButton>
    </div>
  );
}

// ─── Primitives ───────────────────────────────────────────────────────────────

function BubbleButton({
  active,
  disabled,
  onClick,
  className,
  title,
  children,
}: {
  active?: boolean;
  disabled?: boolean;
  onClick: () => void;
  className?: string;
  title?: string;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      title={title}
      disabled={disabled}
      onClick={onClick}
      className={cn(
        "flex h-7 min-w-7 items-center justify-center rounded px-1 text-muted-foreground transition-colors",
        "hover:bg-muted hover:text-foreground active:scale-[0.93]",
        active && "bg-primary text-primary-foreground hover:bg-primary hover:text-primary-foreground",
        "disabled:pointer-events-none disabled:opacity-30",
        className,
      )}
    >
      {children}
    </button>
  );
}

function Divider() {
  return <div className="my-0.5 h-px w-4 shrink-0 bg-border" />;
}

// ─── Alignment icons ──────────────────────────────────────────────────────────

function AlignLeftIcon() {
  return (
    <svg width="13" height="13" viewBox="0 0 12 12" fill="currentColor">
      <rect x="0" y="1.5" width="12" height="1.5" rx="0.5" />
      <rect x="0" y="5" width="7" height="1.5" rx="0.5" />
      <rect x="0" y="8.5" width="10" height="1.5" rx="0.5" />
    </svg>
  );
}

function AlignCenterIcon() {
  return (
    <svg width="13" height="13" viewBox="0 0 12 12" fill="currentColor">
      <rect x="0" y="1.5" width="12" height="1.5" rx="0.5" />
      <rect x="2.5" y="5" width="7" height="1.5" rx="0.5" />
      <rect x="1" y="8.5" width="10" height="1.5" rx="0.5" />
    </svg>
  );
}

function AlignRightIcon() {
  return (
    <svg width="13" height="13" viewBox="0 0 12 12" fill="currentColor">
      <rect x="0" y="1.5" width="12" height="1.5" rx="0.5" />
      <rect x="5" y="5" width="7" height="1.5" rx="0.5" />
      <rect x="2" y="8.5" width="10" height="1.5" rx="0.5" />
    </svg>
  );
}
